solution.solution.cpp:
#include <cstdint>
#include <functional>
#include <string>
#include <vector>

struct Result { std::int32_t status; std::uint64_t information; int completions; };
using Handler = std::function<Result(const std::vector<std::uint8_t>& input, std::uint32_t outLength)>;

class Lcg
{
public:
    explicit Lcg(std::uint32_t seed) : m_state{ seed } {}
    std::uint32_t next() { m_state = m_state * 1664525u + 1013904223u; return m_state; }

private:
    std::uint32_t m_state;
};

std::vector<std::uint8_t> makeInput(Lcg& rng)
{
    const std::uint32_t length{ (rng.next() >> 16) % 41 };
    std::vector<std::uint8_t> input;
    for (std::uint32_t i{ 0 }; i < length; ++i)
    {
        switch ((rng.next() >> 16) % 4)
        {
        case 0: input.push_back(0x00); break;
        case 1: input.push_back(0xFF); break;
        case 2: input.push_back(0x10); break;
        default: input.push_back(static_cast<std::uint8_t>((rng.next() >> 16) & 0xFF)); break;
        }
    }
    return input;
}

std::string fuzz(const Handler& handler, int iterations, std::uint32_t seed)
{
    Lcg rng{ seed };
    for (int i{ 0 }; i < iterations; ++i)
    {
        const std::vector<std::uint8_t> input{ makeInput(rng) };
        const std::uint32_t outLength{ (rng.next() >> 16) % 65 };
        const std::string at{ "iteration " + std::to_string(i) + ": " };
        Result r{};
        try { r = handler(input, outLength); }
        catch (...) { return at + "exception"; }
        if (r.completions != 1) return at + "completed " + std::to_string(r.completions) + " times";
        if (r.status < 0 && r.information != 0) return at + "information on failure";
        if (r.status >= 0 && r.information > outLength) return at + "information exceeds output";
    }
    return std::to_string(iterations) + " iterations, no problems";
}

unitTests:
#include <cstring>
#include <stdexcept>
constexpr std::int32_t BAD = static_cast<std::int32_t>(0xC000000Du), SMALL = static_cast<std::int32_t>(0xC0000023u);
// A careful handler: { u32 size; u32 count; } then count u32 values; replies with their sum (4 bytes).
Result careful(const std::vector<std::uint8_t>& in, std::uint32_t outLength) {
    if (in.size() < 8) return { SMALL, 0, 1 };
    std::uint32_t size, count; std::memcpy(&size, in.data(), 4); std::memcpy(&count, in.data() + 4, 4);
    if (size != 8 || count > (in.size() - 8) / 4) return { BAD, 0, 1 };
    if (outLength < 4) return { SMALL, 0, 1 };
    return { 0, 4, 1 };
}
// The same with the classic overflow: 8 + count * 4 computed in 32 bits.
Result overflowing(const std::vector<std::uint8_t>& in, std::uint32_t outLength) {
    if (in.size() < 8) return { SMALL, 0, 1 };
    std::uint32_t size, count; std::memcpy(&size, in.data(), 4); std::memcpy(&count, in.data() + 4, 4);
    if (8u + count * 4u > in.size()) return { BAD, 0, 1 };
    if (count > (in.size() - 8) / 4) throw std::out_of_range("read past the buffer");     // what would crash the kernel
    if (outLength < 4) return { SMALL, 0, 1 };
    return { 0, 4, 1 };
}
TEST("the generator") {
    Lcg a{ 1 }; CHECK_EQ(a.next(), 1015568748u); CHECK_EQ(a.next(), 1586005467u);
    Lcg b{ 7 }, c{ 7 }; CHECK(makeInput(b) == makeInput(c)); Lcg d{ 3 }; for (int i = 0; i < 50; ++i) CHECK(makeInput(d).size() <= 40);
}
TEST("a careful handler survives") { CHECK_EQ(fuzz(careful, 3000, 42), std::string("3000 iterations, no problems")); }
TEST("finding bugs") {
    CHECK_EQ(fuzz([](const std::vector<std::uint8_t>&, std::uint32_t) { return Result{ 0, 0, 2 }; }, 10, 1), std::string("iteration 0: completed 2 times"));
    CHECK_EQ(fuzz([](const std::vector<std::uint8_t>&, std::uint32_t) { return Result{ BAD, 8, 1 }; }, 10, 1), std::string("iteration 0: information on failure"));
    const std::string r = fuzz([](const std::vector<std::uint8_t>&, std::uint32_t out) { return Result{ 0, 16, 1 }; }, 100, 5);
    CHECK(r.find("information exceeds output") != std::string::npos);
    const std::string o = fuzz(overflowing, 20000, 99); CHECK(o.find("exception") != std::string::npos);
}

